//! Record field tables generated from the vendored EPICS `.dbd` record
//! declarations — the machine-readable spec every `FieldDesc` used to be
//! hand-copied from.
//!
//! @generated by `tools/dbd-codegen` from `crates/mca-rs/dbd/*.dbd`.
//! DO NOT EDIT. Re-run `cargo run -p dbd-codegen -- --write` after changing a
//! vendored `.dbd`. Drift is caught by `dbd_codegen::tests::generated_files_are_not_stale`,
//! which `cargo nextest run` executes — locally and in CI — so a stale table
//! is a failing test, not a comment asking you to remember.
//!
//! What is *not* here, and why:
//!
//! * **`dbCommon` fields.** The port models them once in
//!   [`CommonFields`](epics_base_rs::server::record::CommonFields), so splicing them
//!   into every record table would double-declare them. Base's table emits
//!   them separately as `DB_COMMON_FIELDS` so the two models can be reconciled
//!   (and so a `dbCommon` addition is a diff, not a silent gap).
//! * **`DBF_NOACCESS` rows whose `extra(...)` names an array or a type
//!   this generator has no width for** (`MLOK`, `MLIS`, `BKLNK`, `RPCL`,
//!   ...). C keeps `sizeof` the struct member in `pdbFldDes->size`, and
//!   an array's width is its bound, not its element, so the *descriptor*
//!   is dropped rather than invented — but the NAME is kept
//!   (`record_noaccess_fields`): C's `dbNameToAddr` resolves them, so a
//!   SEARCH for `REC.MLOK` is answered and the refusal lands at channel
//!   creation, and the search gate needs the names to do the same.
//!
//!   A row whose `extra(...)` names a plain scalar — `dbCommon`'s `BKPT`
//!   and `TIME` — or a pointer — `RSET`, `DPVT`, `BPTR`, `PPN`, ... — is
//!   CARRIED, descriptor and width both, because `dbpr` prints it and
//!   `dba` reports its `Field Size` and both read the declaration. A
//!   pointer's width is `sizeof(void *)` of the build, as C's is.
//!   Carried is not servable: `FieldDesc::unreadable` is what refuses
//!   the read, so the SEARCH is answered off the descriptor instead of
//!   off the name list.
//!
//! `slots::<rtype>::<FIELD>` is `FIELD`'s index in `<rtype>`'s field
//! table here, the one numbering a `FieldSlot` uses. Names are as
//! declared; a name that is not a Rust identifier has each other
//! character replaced by `_`, a leading digit prefixed by `_`, and a
//! keyword suffixed by `_`.

#![allow(clippy::all)]

use epics_base_rs::server::record::{Asl, Base, FieldDesc, Special};
use epics_base_rs::types::{DbFieldType, DbfCode};

// ---------------------------------------------------------------------
// `menu(...)` choice tables. The index is the stored `epicsEnum16` and is
// wire-visible (a `DBF_MENU` field is served as `DBR_ENUM`), so the order
// here is the `.dbd` declaration order, verbatim.
// ---------------------------------------------------------------------

/// `menu(mcaCHAS)`
pub static MENU_MCA_CHAS: &[&str] = &["Internal", "External"];

/// `menu(mcaERAS)`
pub static MENU_MCA_ERAS: &[&str] = &["Done", "Erase"];

/// `menu(mcaMODE)`
pub static MENU_MCA_MODE: &[&str] = &["PHA", "MCS", "List"];

/// `menu(mcaR0IP)`
pub static MENU_MCA_R0_IP: &[&str] = &["N", "Y"];

/// `menu(mcaREAD)`
pub static MENU_MCA_READ: &[&str] = &["Done", "Read"];

/// `menu(mcaSTRT)`
pub static MENU_MCA_STRT: &[&str] = &["Done", "Acquire"];

/// Every `menu()` declared by a vendored `.dbd`, keyed by its EPICS name.
///
/// This is the table `get_enum_strs` answers a `DBF_MENU` field from: the
/// field's [`FieldDesc::menu`] already points at its choices, and this map
/// exists for the by-name lookups (`.db` loading, `dbpr`).
pub fn menu_choices(menu: &str) -> Option<&'static [&'static str]> {
    Some(match menu {
        "mcaCHAS" => MENU_MCA_CHAS,
        "mcaERAS" => MENU_MCA_ERAS,
        "mcaMODE" => MENU_MCA_MODE,
        "mcaR0IP" => MENU_MCA_R0_IP,
        "mcaREAD" => MENU_MCA_READ,
        "mcaSTRT" => MENU_MCA_STRT,
        _ => return None,
    })
}

/// Every `menu()` this target declares: EPICS name, `choice()` identifiers,
/// and choice values — the three columns `dbWriteMenuFP` prints
/// (`dbStaticLib.c:919-924`), which is what `dbDumpMenu` reports.
///
/// C walks `pdbbase->menuList` in `.dbd` LOAD order. A compiled-in table has
/// no load order, so the rows are in name order; the per-menu choice order is
/// still the `.dbd` order, because that one is the wire-visible index.
pub static MENUS: &[(&str, &[&str], &[&str])] = &[
    (
        "mcaCHAS",
        &["mcaCHAS_Internal", "mcaCHAS_External"],
        MENU_MCA_CHAS,
    ),
    ("mcaERAS", &["mcaERAS_Done", "mcaERAS_Erase"], MENU_MCA_ERAS),
    (
        "mcaMODE",
        &["mcaMODE_PHA", "mcaMODE_MCS", "mcaMODE_List"],
        MENU_MCA_MODE,
    ),
    ("mcaR0IP", &["mcaR0IP_N", "mcaR0IP_Y"], MENU_MCA_R0_IP),
    ("mcaREAD", &["mcaREAD_Done", "mcaREAD_Read"], MENU_MCA_READ),
    (
        "mcaSTRT",
        &["mcaSTRT_Done", "mcaSTRT_Acquire"],
        MENU_MCA_STRT,
    ),
];

/// Every `variable()` this target's `.dbd`s declare, as EPICS name and
/// declared type — the two columns `dbWriteVariableFP` prints
/// (`dbStaticLib.c:1136-1149`), which is what `dbDumpVariable` reports.
///
/// Name order, which is also C's: `dbVariable` appends in load order, but
/// the loaded `.dbd` is `dbExpand` output and that tool emits each
/// declaration family sorted (measured in an installed `softIoc.dbd`).
pub static VARIABLES: &[(&str, &str)] = &[];

